int main(void){@autoreleasepool{[NSApplication sharedApplication];AppDelegate *app=[AppDelegate new];NavigatorView *view=[[NavigatorView alloc]initWithFrame:NSMakeRect(0,0,100,100)];app.navigatorView=view;NSBitmapImageRep *bitmap=[[NSBitmapImageRep alloc]initWithBitmapDataPlanes:NULL pixelsWide:4 pixelsHigh:4 bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:16 bitsPerPixel:32];for(int i=0;i<16;i++){bitmap.bitmapData[i*4]=40;bitmap.bitmapData[i*4+1]=80;bitmap.bitmapData[i*4+2]=120;bitmap.bitmapData[i*4+3]=255;}NSImage *image=[[NSImage alloc]initWithSize:NSMakeSize(4,4)];[image addRepresentation:bitmap];view.image=image;assert(view.image==image&&view.displayGain==1);NSSlider *slider=[NavigatorBrightnessSlider sliderWithValue:20 minValue:-20 maxValue:20 target:app action:@selector(navigatorBrightnessChanged:)];RenderOptions before=app.formulaSettings;[app navigatorBrightnessChanged:slider];assert(view.displayGain>3.6&&((NSBitmapImageRep *)view.image.representations.firstObject).bitmapData[0]>40);RenderOptions after=app.formulaSettings;assert(bitmap.bitmapData[0]==40&&!memcmp(&before,&after,sizeof before));view.image=image;assert(view.image!=image&&view.unadjustedImage==image);slider.doubleValue=0;[app navigatorBrightnessChanged:slider];assert(view.image==image&&view.displayGain==1);slider.doubleValue=-10;[app navigatorBrightnessChanged:slider];assert(((NSBitmapImageRep *)view.image.representations.firstObject).bitmapData[0]<40);NSEvent *reset=[NSEvent mouseEventWithType:NSEventTypeLeftMouseDown location:NSZeroPoint modifierFlags:NSEventModifierFlagCommand timestamp:0 windowNumber:0 context:nil eventNumber:0 clickCount:1 pressure:1];[slider mouseDown:reset];assert(slider.doubleValue==0&&view.displayGain==1&&view.image==image);NavigatorView *fresh=[[NavigatorView alloc]initWithFrame:NSZeroRect];assert(fresh.displayGain==1);puts("Brightness affects only display copies, survives preview replacement, returns exactly to neutral and starts neutral in a new Navigator.");}return 0;}
